from lib import *
S = SS('k105')
F1 = [['fieldRef', 'metadata.name / namespace / uid'], ['spec / status', 'nodeName、serviceAccountName、podIP、hostIP'], ['labels[\'k\'] / annotations[\'k\']', '单个键可以'], ['整个 labels map', '环境变量里不行']]
F2 = [['limits.cpu 0.5 核', 'CPU_LIMIT=1(向上取整)'], ['divisor: 1m', '500'], ['limits.memory 128Mi', '134217728 字节 / divisor 1Mi → 128'], ['没写 limits', '退回节点 allocatable']]
F3 = [['downwardAPI 卷', 'labels / annotations / cpu_limit 文件'], ['kubectl label', '1 秒后文件变化'], ['环境变量 LABEL_TIER', '仍是创建时的 web'], ['文件是符号链接', '..data 原子切换']]
F4 = [['metadata.labels 当环境变量', '拒绝:Unsupported value'], ['status.phase', '拒绝'], ['spec.containers[0].name', 'field label not supported'], ['卷里写 status.phase', '拒绝:只支持 5 项']]
PANELS = [('f', 'flow', 'Downward API'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("fieldRef 能直接读的环境变量:POD_NAME=me、POD_NS=k105、POD_UID(与 Pod 对象的 uid 一致)、NODE_NAME=kx-main-worker、SA_NAME=default、POD_IP=10.244.1.149、HOST_IP=172.18.0.2;单个标签和注解也可以用 metadata.labels['app'](LABEL_APP=demo)、metadata.annotations['owner'](ANN_OWNER=team-a)。", f=fl(F1, cur=[0, 1, 2], mark=[3]), t=tl(S(1), done=lidx(S(1), 'POD_NAME', 'POD_IP', 'LABEL_APP', '对照 Pod 对象')), kv=KV([['Pod 自己的信息', '名字、命名空间、uid、节点、IP'], ['单个标签/注解', "metadata.labels['k'] 的写法"], ['不用调 API', '不需要 RBAC,也不需要 ServiceAccount 令牌']], ['不用调 API'])),
    step("resourceFieldRef:容器 limits.cpu 是 500m,默认 divisor 下 CPU_LIMIT=1(向上取整成核),divisor: 1m 时 CPU_LIMIT_M=500;limits.memory 是 128Mi,默认 MEM_LIMIT=134217728(字节),divisor: 1Mi 时 MEM_LIMIT_MI=128,requests.memory 的 MEM_REQ_MI=64。没有写 limits 的容器:CPU_LIMIT_M=10000、MEM_LIMIT_MI=7935,正好是节点的 allocatable(10 核、8124516Ki),不是 0 或空。", f=fl(F2, cur=[0, 1, 2], mark=[3]), t=tl(S(2), mark=lidx(S(2), 'CPU_LIMIT    =', 'MEM_LIMIT    ='), done=lidx(S(2), 'CPU_LIMIT_M  =', 'MEM_LIMIT_MI =', '没有写 limits')), kv=KV([['divisor 决定单位', '不写就是核 / 字节'], ['没有 limit', '得到的是节点 allocatable,不是“无限”标记'], ['用途', '让应用按容器 limit 调整线程数 / 堆大小']], ['divisor'])),
    step("downwardAPI 卷里的文件:labels 是 app=\"demo\"、tier=\"web\" 每行一个,annotations 是 owner=\"team-a\"(另有 kubernetes.io 的注解),cpu_limit 是 500。用 kubectl label 把 tier 改成 db 并新增 extra=yes:文件 1 秒后变成 app=\"demo\"、extra=\"yes\"、tier=\"db\";而环境变量 LABEL_TIER 仍是创建时的 web(环境变量启动时一次性取值)。文件路径是 ..data 下的符号链接,更新是原子切换,同 ConfigMap。与 ConfigMap 挂载的 60~90 秒延迟不同,这里只用了约 1 秒。", f=fl(F3, cur=[1, 2], done=[0, 3]), t=tl(S(3), mark=lidx(S(3), '用 kubectl label'), done=lidx(S(3), '/etc/podinfo/labels', '同一时刻环境变量', '文件路径是符号链接')), kv=KV([['卷会更新', '标签/注解变化约 1 秒内同步到文件'], ['环境变量不会', '重启容器才变'], ['比 ConfigMap 快', '由 kubelet 的 Pod 同步驱动,不依赖 60 秒的周期']], ['卷会更新'])),
    step("不支持的写法会在创建时被拒:环境变量 fieldPath: metadata.labels(整个 map)→ Unsupported value,supported values: metadata.name、metadata.namespace、metadata.uid、spec.nodeName、spec.serviceAccountName、status.hostIP、status.hostIPs、status.podIP、status.podIPs;status.phase 同样被拒;spec.containers[0].name 报 field label not supported;拼错的 metadata.nam 报 Invalid value … field label not supported。卷里支持的 fieldPath 更少也更特殊:metadata.annotations、metadata.labels、metadata.name、metadata.namespace、metadata.uid,写 status.phase 被拒。", f=fl(F4, cur=[0, 1, 2, 3]), t=tl(S(4), done=lidx(S(4), 'metadata.labels(整个', 'status.phase', 'spec.containers', '卷里写')), kv=KV([['环境变量的白名单', 'name / namespace / uid / 节点 / SA / IP'], ['卷的白名单', 'name / namespace / uid / labels / annotations'], ['要别的信息', '还是得调 API(并配 RBAC)']], ['白名单'])),
]
A = mkartk('k105', 105, 'Kubernetes,Downward API,fieldRef,resourceFieldRef,环境变量,真实验证,动画演示',
    '在 kind 集群里实测 Downward API:fieldRef 把 Pod 名、命名空间、uid、节点、ServiceAccount、Pod IP、Host IP 以及 metadata.labels[\'k\'] 单个键注入环境变量;resourceFieldRef 的 divisor 决定单位(0.5 核默认变 1,divisor 1m 变 500),没写 limits 时得到节点的 allocatable;downwardAPI 卷里的 labels 文件在 kubectl label 之后 1 秒就更新而环境变量不变;不支持的 fieldPath(metadata.labels、status.phase 等)创建时被拒。',
    '容器怎么知道自己叫什么、跑在哪个节点、有多少 CPU?环境变量和卷里的 Downward API 有什么区别?改了标签,容器里能看到吗?没写 limits 会得到什么?这篇把所有支持的写法和拒绝的写法都跑一遍。',
    [('1 秒', '改了 Pod 标签后,downwardAPI 卷里的 labels 文件更新所用的时间(环境变量不变)'), ('500 / 1', '限 500m 的容器,divisor 1m 时 CPU_LIMIT_M=500,默认 divisor 时 CPU_LIMIT=1'), ('allocatable', '没写 limits 的容器通过 resourceFieldRef 读到的是节点的 allocatable(10 核、7935Mi)')],
    [('环境变量:fieldRef', '<p>能直接读的:<code>metadata.name</code> → <code>POD_NAME=me</code>、<code>metadata.namespace</code> → <code>k105</code>、<code>metadata.uid</code>(与 Pod 对象一致)、<code>spec.nodeName</code> → <code>kx-main-worker</code>、<code>spec.serviceAccountName</code> → <code>default</code>、<code>status.podIP</code> → <code>10.244.1.149</code>、<code>status.hostIP</code> → <code>172.18.0.2</code>;单个标签和注解也可以:<code>metadata.labels[\'app\']</code> → <code>demo</code>、<code>metadata.annotations[\'owner\']</code> → <code>team-a</code>。全程不用调 API Server,也不需要 RBAC 和令牌。</p>'),
     ('resourceFieldRef 与 divisor', '<p>容器 <code>limits.cpu</code> 是 500m:默认 divisor 下 <code>CPU_LIMIT=1</code>(向上取整成核),<code>divisor: 1m</code> 时 <code>CPU_LIMIT_M=500</code>;<code>limits.memory</code> 是 128Mi:默认 <code>MEM_LIMIT=134217728</code>(字节),<code>divisor: 1Mi</code> 时 <code>MEM_LIMIT_MI=128</code>,<code>requests.memory</code> 的 <code>MEM_REQ_MI=64</code>。没有写 limits 的容器:<code>CPU_LIMIT_M=10000</code>、<code>MEM_LIMIT_MI=7935</code>,正好是节点的 allocatable(10 核、8124516Ki),不是 0 或空——所以应用按这个数字调线程数时,没设 limit 的容器会把整个节点当成自己的。</p>'),
     ('卷会更新,环境变量不会', '<p>downwardAPI 卷里的文件:<code>labels</code> 是 <code>app="demo"</code>、<code>tier="web"</code> 每行一个,<code>annotations</code> 里有 <code>owner="team-a"</code>,<code>cpu_limit</code> 是 500。用 <code>kubectl label</code> 把 <code>tier</code> 改成 <code>db</code> 并新增 <code>extra=yes</code>:文件 1 秒后变成 <code>app="demo"</code>、<code>extra="yes"</code>、<code>tier="db"</code>;而环境变量 <code>LABEL_TIER</code> 仍是创建时的 <code>web</code>。文件路径是 <code>..data</code> 下的符号链接,更新是原子切换。与 ConfigMap 挂载常见的 60~90 秒延迟(见 k56)不同,这里约 1 秒就同步了。</p>'),
     ('白名单', '<p>不支持的写法在创建时就被拒:环境变量 <code>fieldPath: metadata.labels</code>(整个 map)→ <code>Unsupported value</code>,<code>supported values</code> 只有 <code>metadata.name</code>、<code>metadata.namespace</code>、<code>metadata.uid</code>、<code>spec.nodeName</code>、<code>spec.serviceAccountName</code>、<code>status.hostIP(s)</code>、<code>status.podIP(s)</code>;<code>status.phase</code> 同样被拒;<code>spec.containers[0].name</code>、拼错的 <code>metadata.nam</code> 报 <code>field label not supported</code>。卷里支持的 <code>fieldPath</code> 是另一张表:<code>metadata.annotations</code>、<code>metadata.labels</code>、<code>metadata.name</code>、<code>metadata.namespace</code>、<code>metadata.uid</code>,写 <code>status.phase</code> 被拒。要别的信息,还得调 API Server(并配 RBAC)。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0),Pod 固定在 worker;环境变量与文件内容用 kubectl exec 读取;“1 秒”是 1 秒间隔轮询的结果;非法 fieldPath 用 --dry-run=server 验证;每种情形各一次(各次运行里 Pod 的 uid、IP 不同)',
     '没有验证:status.podIPs / hostIPs 在双栈下的格式;limits.ephemeral-storage 与 hugepages 的 resourceFieldRef;环境变量 expansion($(VAR))引用 Downward API 变量;downwardAPI 卷的 mode 与 defaultMode;projected 卷里组合 downwardAPI(见 k55);Pod 里的 /etc/hosts、hostname 与 Downward API 的关系'],
    'Downward API', PANELS)
